import type { SpecUnit } from "../../lib/specs";
import type { PhysicsWorkshopId } from "../../lib/sandboxes/physics";
import { widgetDirective } from "../../lib/content/widget-registry";

type Exercise = readonly [title: string, question: string, answer: string];
type Session = {
  title: string;
  concepts: string[];
  goal: string;
  prerequisites: string;
  intuition: string;
  theory: string;
  visual: readonly [PhysicsWorkshopId, string];
  mistakes: string;
  example: Exercise;
  assessment: readonly [Exercise, Exercise, Exercise, Exercise];
  prediction: Exercise;
};

function exercise([title, question, answer]: Exercise) {
  return `:::exercise ${title}\n${question}\n:::answer\n${answer}\n:::end`;
}

function session(data: Session): SpecUnit["sessions"][number] {
  const [model, instruction] = data.visual;
  return {
    title: data.title,
    concepts: data.concepts,
    visual: null,
    markdown: [
      "## Learning goal\n" + data.goal,
      "## Prerequisites\n" + data.prerequisites,
      "## Intuition first\n" + data.intuition,
      "## Why this works\n" + data.theory,
      "## Visual exploration\n" + instruction + "\n\n" + widgetDirective({ type: "physics_workshop", config: { model } }),
      "## Common mistakes\n" + data.mistakes,
      "## Original worked example\n" + exercise(data.example),
      "## Assessment\n" + data.assessment.map((task, i) =>
        "### " + ["Recognition", "Procedure", "Error correction", "Transfer"][i] + "\n" + exercise(task),
      ).join("\n\n"),
      "## Pause and Predict\n" + exercise(data.prediction),
    ].join("\n\n"),
  };
}

